<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount,watch,nextTick} from 'vue'
import {useRouter} from 'vue-router'
import {useAuthStore} from '@/stores/auth'
import {useFamilyStore} from '@/stores/family'
import {useSmokingStore} from '@/stores/smoking'
import {useEncouragementStore} from '@/stores/encouragement'
import {useMessageStore} from '@/stores/message'
import {getLocalDateString} from '@/utils/date'
import FamilyChat from '@/components/FamilyChat.vue'
import ImmersiveToggle from '../ui/ImmersiveToggle.vue'
import {interactionTraces} from '../domain/interactionTraces'
import IdentityCard from '@/features/identity/ui/IdentityCard.vue'
import ConstellationCanvas from '../ui/ConstellationCanvas.vue'
import type {StudyOptions,StudyTarget} from '../types'
import type {FamilyMemberModel,EncouragementModel} from '@/types/domain'
import type {ReactionType} from '@/api/encouragement'
const reactionNames:Record<string,string>={heart:'微光',clap:'星雨',like:'共振',celebrate:'绽放',fire:'星环',message:'留言鼓励'}
const auth=useAuthStore(),family=useFamilyStore(),smoking=useSmokingStore(),enc=useEncouragementStore(),messages=useMessageStore(),router=useRouter()
const loading=ref(true),error=ref(''),activityWarning=ref(''),unavailable=ref(false),targets=ref<StudyTarget[]>([]),selected=ref<FamilyMemberModel>(),canvas=ref<InstanceType<typeof ConstellationCanvas>>(),chat=ref(false),sceneVersion=ref(0),planUnavailable=ref(false)
const focusedHistory=ref<string>();const historyRows=ref<EncouragementModel[]>([]);const history=ref(false),historyLoading=ref(false),historyError=ref('');
const dialog=ref<HTMLElement>();let previousFocus:HTMLElement|null=null
let generation=0,disposed=false
const supportMembers=computed(()=>family.members.filter(member=>member.role==='supporter'))
const coreState=computed(()=>{if(!family.isQuitter)return undefined;const row=smoking.checkins.find(value=>value.checkinDate===getLocalDateString());return row?{cigarettes:row.cigarettes,score:row.cravingScore??null,mood:row.mood??null}:undefined})
const traces=computed(()=>interactionTraces(family.isQuitter?smoking.checkins:family.selectedQuitter?family.quitterSummaries[family.selectedQuitter.userId]?.checkins??[]:[],enc.items.filter(row=>row.familyId===family.currentFamily?.id&&row.toUserId===(family.isQuitter?auth.user?.id:family.selectedQuitter?.userId))))
const options=computed<StudyOptions>(()=>({traces:traces.value,members:Math.min(2,supportMembers.value.length) as 0|1|2,supporters:supportMembers.value.map(member=>({id:member.userId,label:member.nickname})),scheme:'A',atmosphere:'dark',motion:true,view:'front',density:.8,coreState:coreState.value,plan:{nodes:[],type:'records',status:'empty'},layers:{core:true,orbitA:supportMembers.value.length>0,orbitB:supportMembers.value.length>1,planArc:true,photons:true,relics:false}}))
const canEncourage=computed(()=>family.isSupporter&&family.currentMember?.userId===auth.user?.id&&Boolean(family.selectedQuitter))
const dialogId=computed(()=>selected.value?.userId)
watch(()=>Boolean(selected.value||chat.value||planUnavailable.value||history.value),async opened=>{if(opened){previousFocus=document.activeElement as HTMLElement;await nextTick();dialog.value?.querySelector<HTMLElement>('button')?.focus()}else if(previousFocus?.isConnected)previousFocus.focus()})
function trap(event:KeyboardEvent){if(event.key!=='Tab')return;const nodes=Array.from((event.currentTarget as HTMLElement).querySelectorAll<HTMLElement>('button:not(:disabled),textarea:not(:disabled),a[href]')),first=nodes[0],last=nodes[nodes.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}
async function load(){const token=++generation,user=auth.user?.id;loading.value=true;error.value='';activityWarning.value='';messages.stopRealtime();try{await family.initializeFamily();if(family.isQuitter)await smoking.ensureStatisticsLoaded();else await family.loadQuitterSummaries();if(disposed||token!==generation||user!==auth.user?.id)return;sceneVersion.value++;const id=family.currentFamily?.id;if(id){const results=await Promise.allSettled([enc.loadEncouragements(id),messages.loadMessages(id)]);if(disposed||token!==generation||user!==auth.user?.id)return;if(results.some(row=>row.status==='rejected'))activityWarning.value='部分家庭动态未能读取';messages.startRealtime(id,()=>enc.loadEncouragements(id))}}catch(cause){if(token===generation&&!disposed)error.value=cause instanceof Error?cause.message:'暂时无法读取'}finally{if(token===generation&&!disposed)loading.value=false}}
const historyItems=computed(()=>historyRows.value.filter(row=>row.familyId===family.currentFamily?.id&&row.toUserId===(family.isQuitter?auth.user?.id:family.selectedQuitter?.userId)&&(!focusedHistory.value||row.id===focusedHistory.value)))
async function openHistory(traceId?:string){focusedHistory.value=typeof traceId==='string'?traceId:undefined;historyRows.value=enc.items.slice();history.value=true;historyLoading.value=true;historyError.value='';const id=family.currentFamily?.id,user=auth.user?.id;if(!id){historyLoading.value=false;return}try{const rows=await enc.loadEncouragements(id,100);if(auth.user?.id===user&&family.currentFamily?.id===id)historyRows.value=rows.slice()}catch(cause){if(auth.user?.id===user)historyError.value=cause instanceof Error?cause.message:'历史读取失败'}finally{if(auth.user?.id===user)historyLoading.value=false}}
function replayHistory(row:(typeof historyItems.value)[number]){history.value=false;canvas.value?.playEffect(row.type==='heart'?'glow':row.type==='clap'?'starlight':row.type==='like'?'resonance':row.type==='celebrate'?'bloom':'halo',row.fromUserId)}
function choose(id:string){if(id.startsWith('memory:encouragement:')){void openHistory(id.slice('memory:encouragement:'.length));return}if(id==='plan'){planUnavailable.value=true;return}if(id==='core'){void router.push(family.isQuitter?'/checkin':'/trend');return}const member=family.members.find(row=>row.userId===id);if(member){selected.value=member;void canvas.value?.projectSupporter(id,true)}}
async function close(){const id=dialogId.value;selected.value=undefined;if(id)await canvas.value?.projectSupporter(id,false)}
async function reaction(type:ReactionType){const id=family.currentFamily?.id,to=family.selectedQuitter?.userId,user=auth.user?.id;if(!id||!to||!canEncourage.value)return;error.value='';try{await enc.sendReaction(id,to,type,family.currentMember?.nickname);if(auth.user?.id===user){await close();canvas.value?.playEffect(type==='heart'?'glow':type==='clap'?'starlight':type==='like'?'resonance':type==='celebrate'?'bloom':'halo',user!)}}catch(cause){if(auth.user?.id===user)error.value=cause instanceof Error?cause.message:'发送失败'}}
async function send(content:string){const id=family.currentFamily?.id;if(!id)return;try{await messages.sendText(id,content)}catch(cause){error.value=cause instanceof Error?cause.message:'发送失败'}}
watch(()=>auth.user?.id,()=>{generation++;selected.value=undefined;chat.value=false;planUnavailable.value=false;history.value=false;historyRows.value=[];historyError.value='';targets.value=[];void load()})
onMounted(load);onBeforeUnmount(()=>{disposed=true;generation++;messages.stopRealtime()})
</script>
<template><main class="family-space"><header :inert="selected||chat||planUnavailable||history?true:undefined"><router-link to="/hub" aria-label="返回晶体主页面">NICØ</router-link><span>NICØ</span><ImmersiveToggle/><router-link to="/profile" aria-label="个人中心">◇</router-link></header><nav v-if="family.isSupporter&&family.quitterMembers.length>1" class="family-choice" aria-label="选择戒烟者"><button v-for="member in family.quitterMembers" :key="member.userId" :aria-pressed="family.selectedQuitterId===member.userId" @click="family.selectQuitter(member.userId)">{{member.nickname}}</button></nav><section v-if="loading" class="family-state" role="status">正在读取…</section><section v-else-if="error&&!family.hasFamily" class="family-state" role="alert">{{error}}<button @click="load">重试</button></section><section v-else class="family-stage" :inert="selected||chat||planUnavailable||history?true:undefined"><ConstellationCanvas v-if="!unavailable" :key="sceneVersion" ref="canvas" :options="options" @frame="next=>targets=next" @unavailable="unavailable=true"/><div v-else class="family-fallback"><button aria-label="共同计划" @click="choose('plan')">◎</button><button @click="choose('core')">{{family.isQuitter?'每日打卡':'戒烟数据'}}</button><button v-for="member in supportMembers" :key="member.userId" @click="choose(member.userId)">{{member.nickname}}</button></div><button v-for="target in targets" :key="target.id" class="family-target" :class="{'star-target':target.id.startsWith('memory:')}" :aria-label="target.label" :style="{left:target.x+'px',top:target.y+'px'}" @click="choose(target.id)"><span v-if="target.id.startsWith('memory:')" class="record-star" aria-hidden="true">✦</span></button></section><footer :inert="selected||chat||planUnavailable||history?true:undefined"><button @click="chat=true">家庭动态</button><button @click="openHistory()">鼓励历史</button><router-link to="/profile?section=family">家庭管理</router-link><button v-for="member in supportMembers.slice(2)" :key="member.userId" @click="choose(member.userId)">{{member.nickname}}</button></footer><p v-if="error" class="family-warning" role="alert">{{error}}</p>
 <div v-if="history" class="family-overlay" @click.self="history=false"><section class="enc-history" ref="dialog" @keydown="trap" role="dialog" aria-modal="true" :aria-label="focusedHistory?'鼓励印记':'鼓励历史'" @keydown.esc.stop.prevent="history=false"><button class="family-close" aria-label="关闭鼓励历史" @click="history=false">×</button><p class="history-caption">{{focusedHistory?'鼓励印记':'鼓励历史 · 最近 100 条'}}</p><p v-if="historyLoading" role="status">正在读取…</p><p v-if="historyError" role="alert">{{historyError}}<button @click="openHistory()">重试</button></p><p v-if="!historyLoading&&!historyError&&!historyItems.length">暂无记录</p><ol><li v-for="row in historyItems" :key="row.id"><span class="history-star" aria-hidden="true">✧</span><div><b>{{row.fromNickname}} · {{reactionNames[row.type]??'鼓励'}}</b><time>{{new Date(row.createdAt).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})}}</time><p v-if="row.message">{{row.message}}</p></div><button :aria-label="'重播鼓励 '+row.id" @click="replayHistory(row)">↻</button></li></ol></section></div>
 <div v-if="planUnavailable" class="family-overlay" @click.self="planUnavailable=false"><section ref="dialog" @keydown="trap" role="dialog" aria-modal="true" aria-label="共同计划状态" @keydown.esc.stop.prevent="planUnavailable=false"><button class="family-close" aria-label="关闭共同计划状态" @click="planUnavailable=false">×</button><p>共同计划服务尚未启用</p></section></div>
 <div v-if="selected" class="family-overlay" @click.self="close"><section ref="dialog" @keydown="trap" role="dialog" aria-modal="true" aria-label="家庭成员身份" @keydown.esc.stop.prevent="close"><button class="family-close" @click="close" aria-label="收拢身份晶片">×</button><IdentityCard dark variant="compact" :identity="{nickname:selected.nickname,role:selected.role,accountLabel:selected.userId===auth.user?.id?'本人':'家庭成员'}"/><p v-if="selected.userId===auth.user?.id&&canEncourage">向 {{family.selectedQuitter?.nickname}}</p><div v-if="selected.userId===auth.user?.id&&canEncourage" class="family-reactions"><button v-for="item in ([['heart','微光'],['clap','星雨'],['like','共振'],['celebrate','绽放'],['fire','星环']] as const)" :key="item[0]" :disabled="enc.sending||enc.isReactionCoolingDown(family.selectedQuitter!.userId,item[0])" @click="reaction(item[0])">{{item[1]}}</button></div><small>沿用现有快捷鼓励记录</small></section></div>
 <div v-if="chat" class="family-overlay" @click.self="chat=false"><section class="family-chat-sheet" ref="dialog" @keydown="trap" role="dialog" aria-modal="true" aria-label="家庭动态" @keydown.esc.stop.prevent="chat=false"><button @click="chat=false" class="family-close" aria-label="关闭家庭动态">×</button><FamilyChat compact :messages="messages.items" :encouragements="enc.items" :members="family.members" :current-user-id="auth.user?.id" :reaction-target="canEncourage?family.selectedQuitter:undefined" :sending="messages.sending" :loading="messages.loading||enc.loading" :warning="activityWarning" :realtime-status="messages.realtimeStatus" :reaction-disabled="enc.sending" @send="send" @reaction="reaction" @retry="load"/></section></div>
</main></template>
<style scoped>
.family-space{min-height:100svh;background:#17212a;color:#d9dfe1;font:12px Inter,'Microsoft YaHei',sans-serif}.family-space>header{height:72px;padding:0 4.2%;display:flex;align-items:center;justify-content:space-between}.family-space a{color:inherit;text-decoration:none;letter-spacing:.2em}.family-space header>span{font-size:18px;letter-spacing:.2em}.family-stage{height:calc(100svh - 130px);min-height:480px;position:relative;overflow:hidden}.family-target{position:absolute;transform:translate(-50%,-50%);width:65px;height:65px;border:0;border-radius:50%;background:none;cursor:pointer}.family-target:focus-visible{outline:1px solid #d7b87f}.family-space footer{display:flex;justify-content:center;align-items:center;gap:25px;min-height:58px;font-size:10px}.family-space button{font:inherit;color:inherit;min-height:44px;cursor:pointer}.family-space footer button{border:0;background:none}.family-state{height:65svh;display:grid;place-content:center;gap:15px}.family-overlay{position:fixed;inset:0;z-index:13;background:#10192866;backdrop-filter:blur(2px);display:grid;place-items:center;padding:22px}.family-overlay>section{position:relative;width:min(440px,100%);color:#d6e0e3}.family-overlay small{display:block;text-align:center;font-size:9px;color:#94a4b2;margin:20px 0}.family-close{display:block;margin:0 0 12px auto;width:44px;border:0;background:none;font-size:22px!important}.family-reactions{display:flex;justify-content:center;gap:6px;margin-top:20px}.family-reactions button{border:1px solid #a2b5c144;border-radius:18px;background:#bbc9d511;padding:8px 12px;font-size:11px}.family-reactions button:disabled{opacity:.35}.family-chat-sheet{width:min(750px,100%)!important;max-height:85svh;overflow:auto;background:#f5f4ef;color:#52626c!important;border:1px solid #fff;border-radius:18px;padding:16px}.family-warning{font-size:11px;color:#e5bba0;text-align:center}.family-fallback{display:flex;justify-content:center;align-items:center;gap:12px;height:100%}.family-fallback button,.family-choice button{border:1px solid #a7bdca44;border-radius:22px;background:#e3eff411;padding:8px 16px}.family-choice{display:flex;justify-content:center;gap:10px}@media(max-width:600px){.family-space>header{padding:0 20px}.family-reactions{flex-wrap:wrap}.family-stage{min-height:440px}}
</style>

<style scoped>
.enc-history{padding:18px 24px;background:linear-gradient(140deg,#26313bee,#17222aee);border:1px solid #adbbc433;border-radius:16px;max-height:80svh;overflow:auto}.enc-history ol{list-style:none;padding:0;margin:0}.enc-history li{display:flex;align-items:center;gap:14px;padding:16px 0;border-bottom:1px solid #a7b7c21c}.history-star{font-size:25px;color:#e2c28b}.enc-history li>div{flex:1;min-width:0}.enc-history b{font-size:12px;font-weight:400}.enc-history time{display:block;font-size:10px;color:#a5b4bf;margin-top:6px}.enc-history li p{font-size:11px;overflow-wrap:anywhere;margin-bottom:0}.enc-history li button{width:44px;border:1px solid #c0ccd52b;background:#d0dfec08;border-radius:50%;font-size:22px}.history-caption{font-size:12px;letter-spacing:.08em;margin:0 0 20px}
</style>
<style scoped>
.family-target.star-target{width:38px;height:38px;min-height:38px;z-index:2}.star-target:hover{outline:1px solid #e0c18588;box-shadow:0 0 18px #dfc28c22}@media(max-width:600px){.family-target.star-target{width:44px;height:44px;min-height:44px}}
</style>
<style scoped>
.record-star{color:#ffe3a1;font-size:16px;line-height:1;text-shadow:0 0 8px #efc477,0 0 18px #c9934155;pointer-events:none}.star-target:hover .record-star{font-size:20px}
</style>